package com.dotcms.contenttype.model.type;

import com.dotmarketing.business.Permissionable;

/**
 * The corner of the hierarchy this experiment does NOT claim to have settled.
 *
 * <p>The real ContentType is abstract with nine abstract subclasses, and every concrete class under
 * it — {@code ImmutableSimpleContentType} and friends — is generated by the Immutables annotation
 * processor. A permits clause has to name types that do not exist until that processor has run, in
 * the same compilation. Whether javac accepts that is a question this model cannot answer honestly,
 * because it has no processor; {@link ImmutableSimpleContentType} is hand-written to stand in for a
 * generated class, which is exactly the part that would differ.</p>
 */
public sealed abstract class ContentType implements Permissionable permits SimpleContentType {
}
